import * as React from 'react'
import { buttonVariants, cn, type ButtonVariants } from "@/lib/utils"

import { Slot } from './slot'

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement>, ButtonVariants {
  asChild?: boolean
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : 'button'
    return (
      <Comp
        data-slot="button"
        className={cn(buttonVariants({ variant, size, className }))}
        ref={ref}
        {...props}
      />
    )
  }
)
Button.displayName = 'Button'

export { Button, buttonVariants }

/* packages/weapp/src/button/button.wxss */
@import "../utilities.wxss";

/* Additional resets for Weapp Button if not covered by tailwind utilities */
button {
  margin: 0;
  padding: 0;
  border: none;
  background-color: transparent;
  line-height: normal; /* Check shared config 'leading-normal' matches */
  border-radius: 0;
}

/* Button variants use 'bg-primary' etc from utilities */
/* Hover uses 'hover-bg-primary' etc from utilities */

/* Because we use <button> tag, some user agent styles might persist. 
   The 'w-full' or 'inline-flex' from shared should override display. 
*/

import { buttonVariants } from '../utils'

Component({
  externalClasses: ['ext-class'],
  properties: {
    variant: {
      type: String,
      value: 'default',
    },
    size: {
      type: String,
      value: 'default',
    },
    className: {
      type: String,
      value: '',
    },
  },
  data: {
    baseClass: '',
    hoverClass: '',
  },
  observers: {
    'variant, size, className': function (variant, size, className) {
      this.setData({
        baseClass: buttonVariants({ variant, size, className }),
        hoverClass: '',
      })
    },
  },
  methods: {
    handleTap(e: any) {
      this.triggerEvent('tap', e)
    },
  },
})
